export const ALLOWED_QODER_GATEWAY_ORIGIN = "https://gateway.qoder.com.cn";

export class QoderDestinationSecurityError extends Error {
  constructor(invalidOrigin: string) {
    super(`Security rejection: Qoder gateway origin must be "${ALLOWED_QODER_GATEWAY_ORIGIN}", received "${invalidOrigin}"`);
    this.name = "QoderDestinationSecurityError";
  }
}

export function validateQoderGatewayUrl(urlStr: string): string {
  let parsed: URL;
  try {
    parsed = new URL(urlStr);
  } catch (_e) {
    throw new QoderDestinationSecurityError("invalid-url");
  }
  if (parsed.origin !== ALLOWED_QODER_GATEWAY_ORIGIN) {
    throw new QoderDestinationSecurityError(parsed.origin);
  }
  return urlStr;
}

export function normalizeToolArguments(argsStr: string, toolName?: string): string {
  try {
    let parsed: any;
    try {
      parsed = JSON.parse(argsStr);
    } catch (_e) {
      const trimmed = argsStr.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
      parsed = JSON.parse(trimmed);
    }

    if (!parsed || typeof parsed !== "object") return argsStr;

    while (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      const keys = Object.keys(parsed);
      if (keys.length === 1) {
        const singleKey = keys[0];
        const inner = (parsed as any)[singleKey];
        if (["input", "arguments", "parameters", "params", "properties"].includes(singleKey) && inner && typeof inner === "object" && !Array.isArray(inner)) {
          parsed = inner;
          continue;
        }
      }
      break;
    }

    if (toolName === "executeCode" || toolName === "execute_code" || "code" in parsed || "command" in parsed) {
      if (!("code" in parsed) && parsed.command) {
        parsed.code = parsed.command;
      }
      if (!("intent" in parsed) || parsed.intent === undefined) {
        parsed.intent = parsed.description || parsed.thought || "Execute code in console";
      }
      const codeStr = typeof parsed.code === "string" ? parsed.code : "";
      if (!("capturePlot" in parsed) || parsed.capturePlot === undefined) {
        parsed.capturePlot = /ggplot|plot\(|hist\(|barplot\(|boxplot\(|plt\.|sns\./i.test(codeStr);
      }
      if (!("language" in parsed) || !parsed.language || typeof parsed.language !== "string") {
        if (/import\s+\w+|def\s+\w+|plt\.|pd\.|np\.|print\(|from\s+\w+\s+import/i.test(codeStr)) {
          parsed.language = "python";
        } else {
          parsed.language = "r";
        }
      } else {
        parsed.language = parsed.language.toLowerCase().trim();
      }
    }

    const cleanOptionLabel = (s: string): string =>
      s.replace(/^[\s"“”「」『』]+|[\s"“”「」『』]+$/g, "").trim();

    // Parse a stringified options list without destroying Chinese prose:
    // prefer newline-separated items, then quoted segments, then fall back
    // to comma splitting only when every piece is short. Enumeration marks
    // (、) are never treated as top-level separators since they routinely
    // appear inside a single Chinese option.
    const parseAskUserOptionsString = (s: string): string[] => {
      const lines = s.split(/\r?\n/).map(cleanOptionLabel).filter(Boolean);
      if (lines.length > 1) return lines;
      const quoted: string[] = [];
      // JSON key tokens must never surface as options when falling back to
      // quoted-segment extraction on a half-formed JSON string.
      const keyTokens = new Set(["label", "description", "recommended", "text", "value", "options"]);
      for (const m of s.matchAll(/"([^"]+)"|“([^”]+)”/g)) {
        const q = (m[1] ?? m[2] ?? "").trim();
        if (q && !keyTokens.has(q.toLowerCase())) quoted.push(q);
      }
      if (quoted.length > 1) return quoted;
      const pieces = s.split(/[,;；]/).map(cleanOptionLabel).filter(Boolean);
      if (pieces.length > 1 && pieces.every((p) => p.length > 0 && p.length <= 24)) return pieces;
      return [cleanOptionLabel(s)];
    };

    if (toolName && /^ask[_-]?user$/i.test(toolName)) {
      // Positron's AskUser schema: title (string, required), question (string,
      // required), options (optional array of {label, description?, recommended?}).
      // Weak models omit title or stringify options; repair both so the client-side
      // Zod validation accepts the call instead of bouncing it back to the model.
      if (!parsed.title || typeof parsed.title !== "string" || parsed.title.trim() === "") {
        const src = typeof parsed.question === "string" ? parsed.question.trim() : "";
        if (src) {
          const short = src.split(/\s+/).slice(0, 6).join(" ");
          parsed.title = short.length > 48 ? short.slice(0, 45).trimEnd() + "..." : short;
        } else {
          parsed.title = "Question";
        }
      }
      if (!parsed.question || typeof parsed.question !== "string" || parsed.question.trim() === "") {
        parsed.question = parsed.title;
      }
      if ("options" in parsed) {
        let opts = parsed.options;
        if (typeof opts === "string") {
          // Models frequently stringify the whole options array (valid JSON
          // or half-formed prose). Try a real JSON parse first so object
          // options keep their label/description structure; fall back to the
          // prose heuristics only when that fails.
          try {
            const jsonOpts = JSON.parse(opts);
            if (Array.isArray(jsonOpts)) opts = jsonOpts;
            else opts = parseAskUserOptionsString(opts);
          } catch (_e) {
            opts = parseAskUserOptionsString(opts);
          }
        }
        if (Array.isArray(opts)) {
          parsed.options = opts.map((o: any) => {
            if (typeof o === "string") {
              const lbl = cleanOptionLabel(o).replace(/^label\s*[:：]\s*/i, "");
              return { label: lbl };
            }
            if (o && typeof o === "object") {
              const label = typeof o.label === "string" && o.label.trim() !== ""
                ? o.label
                : typeof o.text === "string" ? o.text : String(o.value ?? "");
              const out: Record<string, any> = { label };
              if (typeof o.description === "string" && o.description.trim() !== "") out.description = o.description;
              if (o.recommended === true || o.recommended === "true") out.recommended = true;
              return out;
            }
            return { label: String(o) };
          });
        } else {
          // Schema allows omitting options entirely; a malformed scalar is worse.
          delete parsed.options;
        }
      }
    }

    if (toolName === "skill") {
      // Positron's skill tool schema is {skill: string} — the name of the skill
      // to load. Weak models omit it or stash the name under an alias key
      // (name/skill_name/...). Recover it from any plausible single alias.
      if (!parsed.skill || typeof parsed.skill !== "string" || parsed.skill.trim() === "") {
        for (const k of ["name", "skill_name", "skillName", "id", "value", "text", "tool", "code"]) {
          if (typeof parsed[k] === "string" && parsed[k].trim() !== "") {
            parsed.skill = parsed[k].trim();
            delete parsed[k];
            break;
          }
        }
      }
    }

    function sanitize(obj: any, keyName?: string): any {
      if (obj === null || obj === undefined) return obj;
      if (typeof obj === "string") {
        const trimmed = obj.trim();
        const lower = trimmed.toLowerCase();
        if (lower === "true") return true;
        if (lower === "false") return false;
        if (keyName && /^(timeout|timeout_?ms|port|line|limit|turns?|turn_?limit|width|height|fig_?width|fig_?height|max_?tokens|max_?output_?tokens|duration|delay|interval|retries|attempts|count|size)$/i.test(keyName)) {
          if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
            const num = Number(trimmed);
            if (!Number.isNaN(num)) return num;
          }
        }
        return obj;
      }
      if (Array.isArray(obj)) {
        return obj.map((item) => sanitize(item, keyName));
      }
      if (typeof obj === "object") {
        const res: Record<string, any> = {};
        for (const [k, v] of Object.entries(obj)) {
          res[k] = sanitize(v, k);
        }
        return res;
      }
      return obj;
    }

    return JSON.stringify(sanitize(parsed));
  } catch (_e) {
    return argsStr;
  }
}

export function messagesToQoderFormat(parsed: OcxParsedRequest): Array<Record<string, any>> {
  const out: Array<Record<string, any>> = [];
  if (parsed.context.systemPrompt && parsed.context.systemPrompt.length > 0) {
    out.push({
      role: "system",
      content: parsed.context.systemPrompt.join("\n"),
    });
  }

  for (const msg of parsed.context.messages) {
    if (msg.role === "user" || (msg as any).role === "developer") {
      // Qoder's gateway only accepts system/user/assistant/tool roles. The
      // Responses-API "developer" role must be mapped to "system", otherwise
      // Qoder answers with an empty stream that surfaces as a premature close.
      const role = (msg as any).role === "developer" ? "system" : "user";
      if (typeof msg.content === "string") {
        out.push({ role, content: msg.content });
      } else if (Array.isArray(msg.content)) {
        const hasImages = msg.content.some((p: any) => p.type === "image" && p.imageUrl);
        if (!hasImages) {
          const text = msg.content
            .filter((p: any) => p.type === "text" || p.type === "input_text")
            .map((p: any) => p.text || "")
            .join("");
          out.push({ role, content: text });
        } else {
          const parts = msg.content.map((p: any) => {
            if (p.type === "text" || p.type === "input_text") return { type: "text", text: p.text || "" };
            if (p.type === "image" && p.imageUrl) {
              return {
                type: "image_url",
                image_url: {
                  url: p.imageUrl,
                  ...(p.detail ? { detail: p.detail } : {}),
                },
              };
            }
            return p;
          });
          out.push({ role, content: parts });
        }
      }
    } else if (msg.role === "assistant") {
      const aMsg = msg as any;
      const chatMsg: Record<string, any> = { role: "assistant" };
      if (typeof aMsg.content === "string") {
        chatMsg.content = aMsg.content;
      } else if (Array.isArray(aMsg.content)) {
        const textParts = aMsg.content.filter((p: any) => p.type === "text" || typeof p === "string");
        const toolCalls = aMsg.content.filter((p: any) => p.type === "toolCall");
        if (textParts.length > 0) {
          chatMsg.content = textParts.map((p: any) => (typeof p === "string" ? p : p.text || "")).join("");
        } else if (toolCalls.length === 0) {
          chatMsg.content = "";
        }
        if (toolCalls.length > 0) {
          chatMsg.tool_calls = toolCalls.map((tc: any, idx: number) => ({
            index: idx,
            id: tc.id || randomUUID(),
            type: "function",
            function: { name: tc.name, arguments: typeof tc.arguments === "string" ? tc.arguments : JSON.stringify(tc.arguments || {}) }
          }));
        }
      } else if (aMsg.content) {
        chatMsg.content = String(aMsg.content);
      } else {
        chatMsg.content = "";
      }
      out.push(chatMsg as any);
    } else if (msg.role === "tool" || (msg as any).role === "toolResult" || (msg as any).role === "tool_result") {
      const tMsg = msg as any;
      let textContent = "";
      if (typeof tMsg.content === "string") {
        textContent = tMsg.content;
      } else if (Array.isArray(tMsg.content)) {
        textContent = tMsg.content
          .filter((p: any) => p.type === "text")
          .map((p: any) => p.text || "")
          .join("");
        if (!textContent && tMsg.content.length > 0) {
          textContent = JSON.stringify(tMsg.content);
        }
      } else if (tMsg.content) {
        textContent = JSON.stringify(tMsg.content);
      }
      out.push({
        role: "tool",
        tool_call_id: tMsg.toolCallId || tMsg.id || tMsg.toolName || "tool",
        content: textContent,
      });
    }
  }
  return out;
}

